#!/usr/bin/env python3
"""Embed hmi/ui/*.xml into a C source file.

Runs as a PlatformIO pre-build script and from the simulator's CMake build.
Standalone: gen_ui_xml.py <ui dir> <output .c>
"""
import os
import sys


def c_string(text):
    out = []
    for line in text.splitlines():
        line = line.replace("\\", "\\\\").replace('"', '\\"')
        out.append('    "%s\\n"' % line)
    return "\n".join(out) or '    ""'


def generate(ui_dir, out_path):
    names = sorted(f[:-4] for f in os.listdir(ui_dir) if f.endswith(".xml"))
    parts = [
        "/* Generated by tools/gen_ui_xml.py from the XML files in hmi/ui. Do not edit. */",
        "#include <string.h>",
        '#include "ui_xml.h"',
        "",
    ]
    for n in names:
        with open(os.path.join(ui_dir, n + ".xml"), encoding="utf-8") as f:
            parts.append("static const char xml_%s[] =\n%s;\n" % (n, c_string(f.read())))
    parts.append("const char *ui_xml_get(const char *name)\n{")
    for n in names:
        parts.append('    if (strcmp(name, "%s") == 0) return xml_%s;' % (n, n))
    parts.append("    return NULL;\n}\n")
    text = "\n".join(parts)

    # Leave the file alone when nothing changed, to avoid needless rebuilds.
    if os.path.exists(out_path):
        with open(out_path, encoding="utf-8") as f:
            if f.read() == text:
                return
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(text)


try:
    Import("env")  # noqa: F821 - provided by PlatformIO
    _root = env.subst("$PROJECT_DIR")  # noqa: F821
    generate(os.path.join(_root, "ui"),
             os.path.join(_root, "lib", "feeder_app", "src", "ui_xml_gen.c"))
except NameError:
    if __name__ == "__main__":
        if len(sys.argv) != 3:
            sys.exit(__doc__)
        generate(sys.argv[1], sys.argv[2])
